  func: (u, v) => {
    const x = u * 2 - 1;
    const y = v * 2 - 1;
    const z = x * x + y * y;
    return [x, y, z];
  },
  uRange: [0, 1],
  vRange: [0, 1]
});

// Create a sphere using parametric equations
const sphere = new Surface3D({
  func: (u, v) => {
    const theta = u * Math.PI * 2;
    const phi = v * Math.PI;
    return [
      Math.sin(phi) * Math.cos(theta),
      Math.sin(phi) * Math.sin(theta),
      Math.cos(phi)
    ];
  }
});
